target.css:
:root {
  --ink: #172c3f;
  --muted: #5d7180;
  --paper: #fffdf6;
  --sky: #dceff2;
  --blue: #247b9c;
  --lime: #caeb78;
  --amber: #f7c35c;
  --line: #b7d0d5;
  --soft: #f1f8f7;
}

* {
  box-sizing: border-box;
}

.launch-card {
  width: 500px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 2px solid var(--ink);
  border-radius: 16px;
}

.launch-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 14px 11px;
  background: var(--sky);
  border-bottom: 2px solid var(--ink);
}

.title-block p,
.metric p {
  margin: 0;
}

.eyebrow {
  color: var(--blue);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1.1px;
}

h1 {
  margin: 3px 0 0;
  font-size: 20px;
  line-height: 1.05;
  letter-spacing: -0.4px;
}

.status-badge {
  padding: 6px 9px;
  color: var(--ink);
  background: var(--lime);
  border: 1px solid var(--ink);
  border-radius: 999px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.7px;
}

.launch-main {
  display: grid;
  grid-template-columns: 1.22fr 0.78fr;
  min-height: 164px;
}

.metrics {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 7px;
  padding: 12px;
  background: var(--soft);
}

.metric {
  display: flex;
  flex-direction: column;
  padding: 9px;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 10px;
}

.metric-icon {
  width: 24px;
  height: 24px;
  display: grid;
  place-items: center;
  margin-bottom: 7px;
  color: var(--paper);
  background: var(--blue);
  border-radius: 7px;
  font-size: 15px;
  font-weight: 800;
}

.metric p {
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  line-height: 1.15;
}

.metric strong {
  margin-top: 4px;
  font-size: 18px;
  line-height: 1;
}

.metric small {
  color: var(--muted);
  font-size: 10px;
}

.metric-note {
  margin-top: auto;
  padding-top: 7px;
  color: var(--blue);
  font-size: 9px;
  font-weight: 700;
  line-height: 1.1;
}

.checklist {
  padding: 13px 14px 10px;
  border-left: 2px solid var(--ink);
}

.checklist-heading {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  padding-bottom: 7px;
  border-bottom: 1px solid var(--line);
}

.checklist h2 {
  margin: 0;
  font-size: 14px;
  line-height: 1;
}

.checklist-heading span {
  color: var(--blue);
  font-size: 10px;
  font-weight: 800;
}

ul {
  display: grid;
  gap: 6px;
  margin: 9px 0 8px;
  padding: 0;
  list-style: none;
}

li {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  font-weight: 600;
}

.check {
  display: grid;
  width: 15px;
  height: 15px;
  place-items: center;
  color: var(--ink);
  background: var(--lime);
  border: 1px solid var(--ink);
  border-radius: 4px;
  font-size: 10px;
  font-weight: 900;
}

.launch-time {
  margin: 0;
  padding: 7px 8px;
  color: var(--muted);
  background: var(--sky);
  border-radius: 6px;
  font-size: 10px;
}

.launch-time strong {
  float: right;
  color: var(--ink);
}

.launch-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 9px 14px;
  background: var(--ink);
  color: var(--paper);
}

.launch-footer p {
  display: flex;
  align-items: center;
  gap: 6px;
  margin: 0;
  font-size: 11px;
  font-weight: 600;
}

.pilot-dot {
  width: 8px;
  height: 8px;
  background: var(--amber);
  border-radius: 50%;
}

button {
  padding: 6px 9px;
  color: var(--ink);
  background: var(--amber);
  border: 1px solid var(--paper);
  border-radius: 6px;
  font-size: 10px;
  font-weight: 800;
}

